original_prompt:
{
  "role": "Image Designer",
  "task": "Create a detailed sticker image with a transparent background.",
  "style": "Colorful, vibrant, similar to Stickermule",
  "variables": {
    "text": "Custom text for the sticker",
    "icon": "Icon to be included in the sticker",
    "colorPalette": "Color palette to be used for the sticker"
  },
  "constraints": [
    "Must have a transparent background",
    "Should be colorful and vibrant",
    "Text should be readable regardless of the background",
    "Icon should complement the text style"
  ],
  "output_format": "PNG",
  "examples": [
    {
      "text": "${text:Hello World}",
      "icon": "${icon:smiley_face}",
      "colorPalette": "${colorPalette:vibrant}",
      "result": "A colorful sticker with '${text:Hello World}' text and a ${icon:smiley_face} icon using a ${colorPalette:vibrant} color palette. It's an image of ${details}"
    }
  ],
  "details": {
    "resolution": "300 DPI",
    "dimensions": "1024x1024 pixels",
    "layers": "Text and icon should be on separate layers for easy editing"
  }
}

vi_prompt:
{
  "role": "Nhà thiết kế hình ảnh (Image Designer)",
  "task": "Tạo một hình ảnh nhãn dán (sticker) chi tiết với nền trong suốt.",
  "style": "Nhiều màu sắc, rực rỡ, tương tự phong cách Stickermule",
  "variables": {
    "text": "Đoạn văn bản tùy biến cho sticker",
    "icon": "Biểu tượng cần đưa vào sticker",
    "colorPalette": "Bảng màu sử dụng cho sticker"
  },
  "constraints": [
    "Bắt buộc phải có nền trong suốt (transparent background)",
    "Màu sắc phải rực rỡ và giàu sức sống",
    "Chữ phải rõ ràng, dễ đọc trên mọi màu nền",
    "Biểu tượng phải hài hòa với phong cách kiểu chữ"
  ],
  "output_format": "PNG",
  "examples": [
    {
      "text": "${text:Hello World}",
      "icon": "${icon:smiley_face}",
      "colorPalette": "${colorPalette:vibrant}",
      "result": "Một chiếc nhãn dán rực rỡ với dòng chữ '${text:Hello World}' và biểu tượng ${icon:smiley_face} sử dụng bảng màu ${colorPalette:vibrant}. Đây là hình ảnh của ${details}"
    }
  ],
  "details": {
    "resolution": "300 DPI",
    "dimensions": "1024x1024 pixel",
    "layers": "Văn bản và biểu tượng nằm trên các lớp (layer) riêng biệt để dễ dàng chỉnh sửa"
  }
}
